params.command:
$ErrorActionPreference='Stop'
Set-Location 'C:\Users\Xxkan\mhw-mods-work-canonical'
git fetch origin --prune
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
$targets=@(
 'fix/release-classifier-workflow-scope-20260929',
 'feature/agent-control-plane-v2-20260928',
 'agent/liveness-scheduler-machine-policy-20260929',
 'agent/agent-control-federation-heartbeat-20260929',
 'feature/agent-control-panel-20260928',
 'agent/game-profile-id-containment-v8.8.5-reconcile',
 'ui/frontend-responsive-polish-20260928',
 'release/v8.8.5-20260929',
 'agent/smart-pack-planner-core',
 'support/updater-publication-input-scope-20260928',
 'integration/smart-pack-planner-main-20260929',
 'integration/smart-pack-planner-main-r2-20260929',
 'agent/heaven-hosted-runner-diagnose-20260929'
)
$active=@()
foreach($line in @(git worktree list --porcelain)){
  if($line -like 'branch refs/heads/*'){ $active += $line.Substring(18) }
}
$deleted=@(); $skipped=@(); $missing=@()
foreach($b in $targets){
  git show-ref --verify --quiet "refs/remotes/origin/$b"
  if($LASTEXITCODE -ne 0){ $missing += $b; continue }
  if($b -in $active){ $skipped += [ordered]@{branch=$b;reason='active-worktree'}; continue }
  git push origin --delete $b
  if($LASTEXITCODE -eq 0){
    $deleted += $b
    git show-ref --verify --quiet "refs/heads/$b"
    if($LASTEXITCODE -eq 0){ git branch -D $b | Out-Null }
  } else { $skipped += [ordered]@{branch=$b;reason='delete-failed'} }
}
git fetch origin --prune | Out-Null
$remaining=@(git for-each-ref --format='%(refname:short)' refs/remotes/origin |
  Where-Object { $_ -ne 'origin/HEAD' -and $_ -like 'origin/*' } |
  ForEach-Object { $_.Substring(7) } | Sort-Object -Unique)
[ordered]@{
  main=(git rev-parse origin/main | Out-String).Trim()
  deleted=$deleted
  skipped=$skipped
  missing=$missing
  remaining_count=$remaining.Count
  remaining=$remaining
  active_worktrees=$active
} | ConvertTo-Json -Depth 5
